format_code:
chip esp32

hardware {
    pin led: Output = 2
}

channel queue: int[8]

task producer {
    every 1s { queue.send(42) }
}

task consumer {
    every 100ms {
        if queue.has_data() {
            var val: int = queue.receive()
        }
    }
}

system_graph.mermaid:
flowchart LR
    c_queue[/"queue"/]
    u_producer(("producer<br>↻ 1s"))
    u_consumer(("consumer<br>↻ 100ms"))
    u_producer -->|send| c_queue
    c_queue -.->|has_data, receive| u_consumer
    classDef task fill:#1f3a4d,stroke:#2B7CB3,color:#e8e8e8;
    classDef timer fill:#33291a,stroke:#d0a83a,color:#f5e9cf;
    classDef machine fill:#2d1f3d,stroke:#7a3ac0,color:#e8e8e8;
